<?php
/** BIGSHOR Wiki Core 29.4.0 — portal data, page tools, activity and reader utilities. */
if (!defined('ABSPATH')) exit;
if (!class_exists('BSW_Phase39_Platform_Completion')) {
final class BSW_Phase39_Platform_Completion {
 public static function init(){
  add_action('init',array(__CLASS__,'types'),25); add_action('add_meta_boxes',array(__CLASS__,'boxes')); add_action('save_post_bsw_portal_item',array(__CLASS__,'save'),10,2);
  add_shortcode('bigshor_recent_changes',array(__CLASS__,'recent')); add_shortcode('bigshor_page_tools',array(__CLASS__,'tools')); add_shortcode('bigshor_watchlist',array(__CLASS__,'watchlist')); add_shortcode('bigshor_languages',array(__CLASS__,'languages')); add_shortcode('bigshor_contributor_directory',array(__CLASS__,'contributors'));
  add_action('wp_enqueue_scripts',array(__CLASS__,'assets')); add_action('wp_ajax_bsw_watch_toggle',array(__CLASS__,'watch_toggle'));
  add_filter('the_content',array(__CLASS__,'article_tools'),55); add_action('rest_api_init',array(__CLASS__,'routes'));
 }
 public static function types(){register_post_type('bsw_portal_item',array('labels'=>array('name'=>'Portal items','singular_name'=>'Portal item','add_new_item'=>'Add portal item'),'public'=>true,'publicly_queryable'=>true,'exclude_from_search'=>true,'has_archive'=>false,'rewrite'=>array('slug'=>'portal-item'),'show_ui'=>true,'show_in_menu'=>true,'supports'=>array('title','editor','excerpt','thumbnail'),'menu_icon'=>'dashicons-calendar-alt'));}
 public static function boxes(){add_meta_box('bsw_portal_data','Portal display settings',array(__CLASS__,'box_html'),'bsw_portal_item','side','high');}
 public static function box_html($p){wp_nonce_field('bsw_portal_save','bsw_portal_nonce');$kind=get_post_meta($p->ID,'_bsw_portal_kind',true);$date=get_post_meta($p->ID,'_bsw_portal_date',true);$url=get_post_meta($p->ID,'_bsw_portal_source',true);echo '<p><label>Section</label><select name="bsw_portal_kind" style="width:100%">';foreach(array('on_this_day'=>'On This Day','ongoing'=>'Ongoing Event','recent_death'=>'Recent Death','did_you_know'=>'Did You Know','featured_picture'=>'Featured Picture') as $k=>$v)echo '<option value="'.esc_attr($k).'" '.selected($kind,$k,false).'>'.esc_html($v).'</option>';echo '</select></p><p><label>Date (MM-DD, for On This Day)</label><input name="bsw_portal_date" value="'.esc_attr($date).'" placeholder="11-05" style="width:100%"></p><p><label>Source URL</label><input type="url" name="bsw_portal_source" value="'.esc_attr($url).'" style="width:100%"></p><p>Publish only after editorial verification. Include sources in the entry content.</p>';}
 public static function save($id,$p){if(defined('DOING_AUTOSAVE')&&DOING_AUTOSAVE)return;if(!isset($_POST['bsw_portal_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['bsw_portal_nonce'])),'bsw_portal_save'))return;if(!current_user_can('edit_post',$id))return;$kind=sanitize_key(wp_unslash($_POST['bsw_portal_kind']??''));$allowed=array('on_this_day','ongoing','recent_death','did_you_know','featured_picture');if(in_array($kind,$allowed,true))update_post_meta($id,'_bsw_portal_kind',$kind);$date=sanitize_text_field(wp_unslash($_POST['bsw_portal_date']??''));if(preg_match('/^(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$/',$date))update_post_meta($id,'_bsw_portal_date',$date);else delete_post_meta($id,'_bsw_portal_date');$url=esc_url_raw(wp_unslash($_POST['bsw_portal_source']??''));if($url)update_post_meta($id,'_bsw_portal_source',$url);else delete_post_meta($id,'_bsw_portal_source');}
 private static function portal($kind,$limit=5,$date=''){ $args=array('post_type'=>'bsw_portal_item','post_status'=>'publish','posts_per_page'=>$limit,'meta_key'=>'_bsw_portal_kind','meta_value'=>$kind,'orderby'=>'date','order'=>'DESC','no_found_rows'=>true);if($date)$args['meta_query']=array(array('key'=>'_bsw_portal_date','value'=>$date,'compare'=>'='));return new WP_Query($args); }
 public static function recent(){ $q=new WP_Query(array('post_type'=>array('wiki_article','bsw_news'),'post_status'=>'publish','posts_per_page'=>20,'orderby'=>'modified','order'=>'DESC'));$o='<section class="bsw-recent-changes"><h2>Recent changes</h2><ul>';while($q->have_posts()){$q->the_post();$o.='<li><a href="'.esc_url(get_permalink()).'">'.esc_html(get_the_title()).'</a> <small>'.esc_html(get_post_type()==='bsw_news'?'News':'Knowledge').' · '.esc_html(get_the_modified_date()).'</small></li>';}$o.='</ul></section>';wp_reset_postdata();return $o; }
 public static function tools(){if(!is_singular())return ''; $id=get_queried_object_id();$o='<nav class="bsw-page-tools" aria-label="Page tools">';$o.='<a href="'.esc_url(get_permalink($id)).'">Permanent link</a> <a href="'.esc_url(get_permalink($id)).'" onclick="window.print();return false">Printable version</a> <a href="'.esc_url(get_edit_post_link($id)?:home_url('/contribute/')).'">'.(current_user_can('edit_post',$id)?'Edit source':'Suggest an edit').'</a> <a href="'.esc_url(get_comments_link($id)).'">Discussion</a> <a href="'.esc_url(get_author_posts_url((int)get_post_field('post_author',$id))).'">Contributor</a>';if(is_user_logged_in())$o.='<button type="button" data-bsw-watch data-post-id="'.(int)$id.'" aria-pressed="false">☆ Add to watchlist</button>'; $o.='</nav>';return $o; }
 public static function article_tools($content){if(!is_singular('wiki_article')||!in_the_loop()||!is_main_query())return $content;return $content.self::tools();}
 public static function watchlist(){if(!is_user_logged_in())return '<p>Please sign in to use your watchlist.</p>';$ids=get_user_meta(get_current_user_id(),'bsw_watchlist',true);$ids=is_array($ids)?$ids:array();$o='<section class="bsw-watchlist"><h2>Your watchlist</h2><ul>';foreach($ids as $id){$p=get_post((int)$id);if($p&&$p->post_status==='publish')$o.='<li><a href="'.esc_url(get_permalink($p)).'">'.esc_html(get_the_title($p)).'</a></li>';}$o.='</ul></section>';return $o;}
 public static function watch_toggle(){check_ajax_referer('bsw_watch');if(!is_user_logged_in())wp_send_json_error(array('message'=>'Sign in required'),401);$id=absint($_POST['post_id']??0);if(!$id||get_post_status($id)!=='publish')wp_send_json_error(array('message'=>'Invalid page'),400);$ids=get_user_meta(get_current_user_id(),'bsw_watchlist',true);$ids=is_array($ids)?array_map('absint',$ids):array();if(in_array($id,$ids,true)){$ids=array_values(array_diff($ids,array($id)));$watch=false;}else{$ids[]=$id;$ids=array_values(array_unique($ids));$watch=true;}update_user_meta(get_current_user_id(),'bsw_watchlist',$ids);wp_send_json_success(array('watching'=>$watch));}
 public static function languages(){ $langs=array('English','العربية','हिन्दी','اردو','বাংলা','తెలుగు','ಕನ್ನಡ','தமிழ்','Français','Español');$o='<nav class="bsw-language-list" aria-label="Available languages"><h2>Languages</h2><ul>';foreach($langs as $l)$o.='<li>'.esc_html($l).'</li>';$o.='</ul><p>Language editions require separately maintained and reviewed content; this directory does not imply translations exist.</p></nav>';return $o; }
 public static function contributors(){ $users=get_users(array('role__in'=>array('administrator','editor','author','contributor'),'number'=>50,'orderby'=>'display_name'));$o='<section class="bsw-contributors"><h2>Contributors</h2><ul>';foreach($users as $u)$o.='<li><a href="'.esc_url(get_author_posts_url($u->ID)).'">'.esc_html($u->display_name).'</a></li>';$o.='</ul></section>';return $o; }
 public static function assets(){if(!is_singular('wiki_article'))return;wp_enqueue_script('bsw-phase39',plugins_url('../assets/phase39.js',__FILE__),array(), '29.4.0',true);wp_localize_script('bsw-phase39','BSWPhase39',array('ajax'=>admin_url('admin-ajax.php'),'nonce'=>wp_create_nonce('bsw_watch')));}
 public static function routes(){register_rest_route('bigshor/v1','/activity',array('methods'=>'GET','permission_callback'=>'__return_true','callback'=>function(){ $q=new WP_Query(array('post_type'=>array('wiki_article','bsw_news'),'post_status'=>'publish','posts_per_page'=>15,'orderby'=>'modified','order'=>'DESC'));$a=array();foreach($q->posts as $p)$a[]=array('title'=>get_the_title($p),'url'=>get_permalink($p),'modified'=>get_post_modified_time('c',true,$p),'type'=>$p->post_type);return rest_ensure_response($a);}));}
}}
BSW_Phase39_Platform_Completion::init();
